import { useNavigate } from 'react-router'

import {
  Box,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  type SelectChangeEvent,
  Typography,
  useTheme
} from '@mui/material'

import { ALL_SEMESTER_FILTER_VALUE } from 'src/data/semesterFilter'

import ReviewGrid from 'src/components/ReviewGrid'

import { useGetRecentReviews } from 'src/hooks/api/review'
import {
  formatSemesterFilterOptionLabel,
  type SemesterFilterValue,
  useSemesterFilteredReviews
} from 'src/hooks/useSemesterFilteredReviews'

const MAX_RECENT_REVIEW_COUNT = 12
const CLUB_PAGE_PATH_PREFIX = '/club'

const RecentReviews = () => {
  const theme = useTheme()
  const navigate = useNavigate()
  const { data: recentReviews } = useGetRecentReviews(MAX_RECENT_REVIEW_COUNT)
  const {
    selectedSemesterFilterValue,
    setSelectedSemesterFilterValue,
    semesterFilterOptions,
    semesterFilteredReviews
  } = useSemesterFilteredReviews(recentReviews)

  const handleSemesterSelectChange = (event: SelectChangeEvent<string>) => {
    setSelectedSemesterFilterValue(event.target.value as SemesterFilterValue)
  }

  const handleReviewCardClick = (clubId: number) => {
    navigate(`${CLUB_PAGE_PATH_PREFIX}/${clubId}`)
  }

  return (
    <Box
      component="section"
      sx={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        gap: theme.spacing(2, 0),
        padding: theme.spacing(5, 4),
        [theme.breakpoints.down('sm')]: {
          padding: theme.spacing(2, 4)
        }
      }}
    >
      <Typography variant="h3" component="h2">
        따끈따끈한 동아리 후기
      </Typography>
      <Box sx={{ width: '100%', maxWidth: '1220px', display: 'flex', justifyContent: 'flex-end', mb: 2 }}>
        <FormControl size="small" sx={{ minWidth: 120 }}>
          <InputLabel id="semester-select-label">학기</InputLabel>
          <Select
            labelId="semester-select-label"
            id="semester-select"
            value={selectedSemesterFilterValue}
            label="학기"
            onChange={handleSemesterSelectChange}
          >
            <MenuItem value={ALL_SEMESTER_FILTER_VALUE}>전체</MenuItem>
            {semesterFilterOptions.map(semesterFilterOption => (
              <MenuItem key={semesterFilterOption} value={semesterFilterOption}>
                {formatSemesterFilterOptionLabel(semesterFilterOption)}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
      </Box>
      <Box sx={{ width: '100%', maxWidth: '1220px' }}>
        <ReviewGrid reviews={semesterFilteredReviews || []} onReviewCardClick={handleReviewCardClick} />
      </Box>
    </Box>
  )
}

export default RecentReviews
