import { useSnackbar } from 'notistack'
import { Helmet } from 'react-helmet-async'
import { useNavigate } from 'react-router'

import { useTheme } from '@mui/material'

import { CATEGORY_MAIN } from 'src/data/categories'
import { CLUB_SEARCH_MESSAGE } from 'src/data/messages'

import Catchphrase from 'src/components/Catchphrase'
import Searchbox from 'src/components/Searchbox'

import RecruitingClubs from 'src/content/index/Index/RecruitingClubs'

import RecentActivities from './RecentActivities'
import RecentReviews from './RecentReviews'

const Index = () => {
  const theme = useTheme()
  const navigate = useNavigate()
  const { enqueueSnackbar } = useSnackbar()

  const handleSubmit: React.FormEventHandler<HTMLFormElement> = event => {
    event.preventDefault()
    const search = document.getElementById('search') as HTMLInputElement
    navigate(`search?name=${search.value}`)
  }

  const handleClickCategory: React.MouseEventHandler<HTMLButtonElement> = event => {
    const categoryMain = event.currentTarget.getAttribute('data-value') as CATEGORY_MAIN

    if (categoryMain !== null && !Object.values(CATEGORY_MAIN).includes(categoryMain)) {
      enqueueSnackbar(CLUB_SEARCH_MESSAGE.WRONG_CATEGORY, { variant: 'warning' })
      return
    }
    const search = document.getElementById('search') as HTMLInputElement
    navigate(`search?name=${search.value}&categoryMain=${categoryMain}`)
  }

  return (
    <>
      <Helmet>
        <title>KLUB :: All the Clubs on KLUB</title>
      </Helmet>
      <Catchphrase>
        <Searchbox searchDefaultValue={''} handleSubmit={handleSubmit} handleClickCategory={handleClickCategory} />
      </Catchphrase>
      <RecruitingClubs theme={theme} />
      <RecentActivities />
      <RecentReviews />
    </>
  )
}

export default Index
